import {splitCue} from './transcript-core.js';
import {createCoverStudio} from './cover-studio.js';
import {captionStyle,validateCues,coverSettings,COVER_STYLES,wrapText} from './editor-controls-core.js';
import {brandKits,activeBrand} from './brand-kits.js';
const e=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const button=(text,fn,cls='')=>{const b=e('button',cls,text);b.type='button';b.onclick=fn;return b};
function field(text,type,value){const label=e('label','control-field',text),input=e(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=value??'';input.setAttribute('aria-label',text);label.append(input);return {label,input}}
function select(text,values,value){const label=e('label','control-field',text),input=e('select');for(const [id,name]of Object.entries(values)){const o=e('option','',name);o.value=id;input.append(o)}input.value=value;input.setAttribute('aria-label',text);label.append(input);return {label,input}}
function dialog(title){const d=e('dialog','editor-control-dialog'),h=e('div','control-heading');h.append(e('h2','',title),button('×',()=>d.close(),'control-close'));h.lastChild.setAttribute('aria-label','Закрыть');d.append(h);d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>d.remove());document.body.append(d);return d}
export function mountEditorControls(api){const {getState,commit,total,seek,getTime,canvas,assetBy,clipAt,download,toast,pause,creationAllowed}=api;
 const pane=document.querySelector('#inspect-captions'),raw=pane.querySelector('#subtitle-text'),oldApply=pane.querySelector('#apply-subtitles');
 const advanced=e('details','caption-advanced');advanced.append(e('summary','','Расширенный текстовый формат'),pane.querySelector('label[for="subtitle-text"]'),raw,oldApply);pane.append(advanced);pane.querySelector('.helper').textContent='Добавьте реплику, укажите начало и конец, затем сохраните. SRT можно импортировать или выгрузить через экспорт.';
 const styles=e('div','caption-style-grid'),rows=e('div','caption-rows'),actions=e('div','caption-actions'),status=e('p','control-status');status.setAttribute('role','status');pane.insertBefore(styles,advanced);pane.insertBefore(rows,advanced);pane.insertBefore(actions,advanced);pane.insertBefore(status,advanced);
 const font=select('Шрифт',{'Golos Text':'Golos Text','Roboto Condensed':'Roboto Condensed'},'Golos Text'),preset=select('Оформление',{karaoke:'Reels · текущее слово',plate:'На подложке',outline:'Контур',plain:'Текст с тенью'},'plate'),position=select('Положение',{bottom:'Снизу',center:'По центру',top:'Сверху'},'bottom'),size=field('Размер, % короткой стороны','number',4.2),safe=field('Отступ от края, %','number',10);size.input.min=2.5;size.input.max=7;size.input.step=.1;safe.input.min=5;safe.input.max=25;safe.input.step=1;const color=field('Цвет субтитров','color','#ffffff'),highlight=field('Цвет активного слова','color','#f4d740');styles.append(font.label,preset.label,position.label,size.label,safe.label,color.label,highlight.label);
 for(const c of [font,preset,position,size,safe,color,highlight])c.input.onchange=async()=>{if(!creationAllowed())return;await document.fonts.load(`500 32px "${font.input.value}"`);commit(()=>getState().captionStyle=captionStyle({...getState().captionStyle,font:font.input.value,style:preset.input.value,position:position.input.value,size:size.input.value,safe:safe.input.value,color:color.input.value,highlight:highlight.input.value}))};
 let draft=[],fingerprint='';
 function drawRows(){rows.replaceChildren();draft.forEach((cue,i)=>{const row=e('div','caption-row'),index=e('span','caption-index',String(i+1).padStart(2,'0')),start=field('Начало, сек','number',cue.start),end=field('Конец, сек','number',cue.end),text=field('Текст реплики','textarea',cue.text);for(const f of [start,end]){f.input.min=0;f.input.max=total();f.input.step=.1;}text.input.rows=2;text.input.maxLength=500;start.input.oninput=()=>{cue.start=Number(start.input.value);delete cue.words};end.input.oninput=()=>{cue.end=Number(end.input.value);delete cue.words};text.input.oninput=()=>{cue.text=text.input.value;delete cue.words;status.textContent='Текст изменён. Проверьте время и сохраните; подсветка слов для изменённой реплики отключена.'};const tools=e('div','caption-row-actions');tools.append(button('К реплике',()=>{pause();seek(Number(cue.start))}),button('Разделить',()=>{const t=getTime();if(t<=cue.start||t>=cue.end){status.textContent='Поставьте курсор внутри этой реплики.';return}try{draft.splice(i,1,...splitCue(cue,t));drawRows()}catch(e){status.textContent=e.message}}),button('Удалить',()=>{draft.splice(i,1);drawRows()}));row.append(index,start.label,end.label,text.label,tools);rows.append(row)});if(!draft.length)rows.append(e('p','control-empty','Пока нет реплик. Добавьте первую или импортируйте SRT.'))}
 actions.append(button('Разбить длинные реплики',()=>{const next=[];for(const cue of draft){const words=String(cue.text).trim().split(/\s+/),parts=[];for(let i=0;i<words.length;i+=7)parts.push(words.slice(i,i+7).join(' '));const step=(cue.end-cue.start)/parts.length;parts.forEach((text,i)=>next.push({start:Math.round((cue.start+i*step)*100)/100,end:Math.round((i===parts.length-1?cue.end:cue.start+(i+1)*step)*100)/100,text}))}draft=next;drawRows();status.textContent='Реплики разбиты на короткие фразы. Проверьте время и сохраните.'}),button('+ Реплика в позиции курсора',()=>{if(!creationAllowed())return;const start=Math.round(getTime()*10)/10;if(total()<=start){status.textContent='Сначала добавьте сцену на таймлайн.';return}draft.push({start,end:Math.min(total(),start+3),text:''});drawRows();rows.lastElementChild?.querySelector('textarea')?.focus()}),button('Сохранить субтитры',()=>{if(!creationAllowed())return;try{const cues=validateCues(draft,total());commit(()=>{getState().cues=cues;getState().captionsEnabled=!!cues.length});status.textContent=`Сохранено реплик: ${cues.length}`}catch(err){status.textContent=err.message}},'primary'));
 function refresh(){const state=getState(),key=JSON.stringify(state.cues);if(key!==fingerprint){fingerprint=key;draft=structuredClone(state.cues||[]);drawRows()}const s=captionStyle(state.captionStyle);font.input.value=s.font;color.input.value=s.color;highlight.input.value=s.highlight;preset.input.value=s.style;position.input.value=s.position;size.input.value=s.size;safe.input.value=s.safe;const cost=document.querySelector('#request-cost');if(cost)cost.textContent=api.requestCost();}
 async function openCover(proposal){return createCoverStudio(api).open(proposal)}
 async function openBrand(){if(!creationAllowed())return;const kits=await brandKits();if(!kits.length){toast('Создайте бренд-кит в разделе «Бренд-киты».');return}const d=dialog('Применить бренд-кит'),form=e('div','brand-apply-form'),kitSelect=select('Бренд-кит',Object.fromEntries(kits.map(k=>[k.id,k.brandName||'Без названия'])),(await activeBrand())?.id),scope=select('Куда применить',{selected:'К выбранной сцене',all:'Ко всем сценам'},'selected'),tagline=field('Заменить заголовок подписью бренда','checkbox','');tagline.input.checked=false;const note=e('p','control-status');form.append(kitSelect.label,scope.label,tagline.label,e('p','helper','Применяются логотип и цвета. Текст сцены останется прежним, если не включить замену заголовка.'),note);d.append(form);const footer=e('div','control-footer');footer.append(button('Убрать бренд со сцен',()=>{const clips=scope.input.value==='all'?getState().clips:getState().clips.filter(c=>c.id===getState().selected);if(!clips.length){note.textContent='Выберите сцену.';return}commit(()=>clips.forEach(c=>{c.brandLogo='';c.accentColor='#fff';c.textColor='#fff'}));d.close()}),button('Применить',()=>{const kit=kits.find(k=>k.id===kitSelect.input.value),clips=scope.input.value==='all'?getState().clips:getState().clips.filter(c=>c.id===getState().selected);if(!clips.length){note.textContent='Добавьте или выберите сцену.';return}commit(()=>clips.forEach(c=>{c.brandLogo=kit.logo||'';c.accentColor=kit.accent;c.textColor=kit.textColor;if(tagline.input.checked)c.title=kit.tagline||c.title}));toast(`Бренд-кит применён: ${clips.length} сцен.`);d.close()},'primary'));d.append(footer);d.showModal()}
 document.querySelector('#apply-brand').onclick=openBrand;const toolbar=document.querySelector('.viewer-toolbar>div:last-child');toolbar.prepend(button('Обложка',()=>openCover()));const cost=e('p','request-cost');cost.id='request-cost';cost.setAttribute('aria-live','polite');document.querySelector('#ai-model-select').parentElement.append(cost);return {refresh,openCover};
}
